package app.kinnect.live;
import android.app.*;import android.content.res.ColorStateList;import android.graphics.Typeface;import android.graphics.drawable.*;import android.os.*;import android.widget.*;import android.view.*;
/** Reports bytes written separately from the server's final response. */
final class UploadProgress implements NativeApi.Progress {
 private final Activity activity;private final Handler ui=new Handler(Looper.getMainLooper());private Dialog dialog;private TextView label;private ProgressBar bar;private boolean closed;private View.OnAttachStateChangeListener lifecycle;
 UploadProgress(Activity owner){activity=owner;ui.post(()->{if(closed||activity.isDestroyed()||activity.isFinishing())return;float d=activity.getResources().getDisplayMetrics().density;int v=WebTheme.isDark(activity)?1:0,card=WebDesign.CARD[v],ink=WebDesign.INK[v],muted=WebDesign.MUTED[v],purple=WebDesign.PURPLE[v],line=WebDesign.LINE[v];LinearLayout box=new LinearLayout(activity);box.setOrientation(1);box.setGravity(Gravity.CENTER_HORIZONTAL);int pad=Math.round(24*d);box.setPadding(pad,Math.round(20*d),pad,Math.round(22*d));GradientDrawable bg=new GradientDrawable();bg.setColor(card);bg.setCornerRadius(Math.round(22*d));bg.setStroke(Math.round(d),line);box.setBackground(bg);TextView title=new KinnectText(activity);title.setText(I18n.t("Đang tải lên…"));title.setTextSize(15);title.setTypeface(ApprovedTypography.font(activity,Typeface.BOLD));title.setTextColor(ink);title.setGravity(Gravity.CENTER);box.addView(title);label=new KinnectText(activity);label.setText("0%");label.setTextSize(22);label.setTypeface(ApprovedTypography.font(activity,Typeface.BOLD));label.setTextColor(purple);label.setGravity(Gravity.CENTER);label.setPadding(0,Math.round(6*d),0,Math.round(12*d));box.addView(label);bar=new ProgressBar(activity,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgressTintList(ColorStateList.valueOf(purple));bar.setProgressBackgroundTintList(ColorStateList.valueOf(line));box.addView(bar,new LinearLayout.LayoutParams(Math.round(220*d),Math.round(8*d)));TextView sub=new KinnectText(activity);sub.setText(I18n.t("Vui lòng giữ màn hình mở"));sub.setTextSize(12);sub.setTextColor(muted);sub.setGravity(Gravity.CENTER);sub.setPadding(0,Math.round(10*d),0,0);box.addView(sub);dialog=new Dialog(activity);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);dialog.setContentView(box);dialog.setCancelable(false);if(dialog.getWindow()!=null){dialog.getWindow().setBackgroundDrawable(new ColorDrawable(0));dialog.getWindow().setDimAmount(0.45f);}dialog.show();lifecycle=new View.OnAttachStateChangeListener(){public void onViewAttachedToWindow(View v){}public void onViewDetachedFromWindow(View v){close();}};activity.getWindow().getDecorView().addOnAttachStateChangeListener(lifecycle);});}
 public void sent(long bytes,long total){ui.post(()->{if(closed||label==null)return;int percent=(int)Math.min(99,bytes*100/Math.max(1,total));label.setText(bytes>=total?I18n.t("Đang hoàn tất…"):percent+"%");bar.setProgress(percent);});}
 void close(){ui.post(()->{closed=true;if(lifecycle!=null)activity.getWindow().getDecorView().removeOnAttachStateChangeListener(lifecycle);if(dialog!=null&&dialog.isShowing())dialog.dismiss();});}
}
